import{_ as a,o as e,c as r,a2 as o}from"./chunks/framework.mRCPFc5l.js";const b=JSON.parse('{"title":"Sync Architecture B","description":"","frontmatter":{"title":"Sync Architecture B"},"headers":[],"relativePath":"operations/sync-architecture-b.md","filePath":"operations/sync-architecture-b.md","lastUpdated":1787839527000}'),d={name:"operations/sync-architecture-b.md"};function n(i,t,c,s,h,l){return e(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="銀行同步-architecture-b" tabindex="-1">銀行同步 Architecture B <a class="header-anchor" href="#銀行同步-architecture-b" aria-label="Permalink to &quot;銀行同步 Architecture B&quot;">​</a></h1><p>規格：<code>docs/audits/bank-sync-20260816/</code>（v1.1 + v1.1.1）。<strong>合約已進碼</strong>；下列是剩餘閘門，不要把 2026-08-16 的「Phase 1 not started」快照當現況。</p><h2 id="階段狀態" tabindex="-1">階段狀態 <a class="header-anchor" href="#階段狀態" aria-label="Permalink to &quot;階段狀態&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Phase</th><th>狀態</th></tr></thead><tbody><tr><td>0A 雙 key 測試</td><td>DONE</td></tr><tr><td>0B dual-key + lookback 3 日</td><td>DONE（程式）</td></tr><tr><td>0C 第一銀行增量真機</td><td><strong>PARTIAL：需重建 APK 真機證明 overlap-only</strong></td></tr><tr><td>1–5 凍結／華南 H0／registry／orchestrator／checkpoint</td><td>DONE</td></tr><tr><td>6 拆 FirstBank 巨石</td><td>INCREMENTAL</td></tr><tr><td>7 遠端 provider tombstone</td><td>DONE</td></tr><tr><td>8 錯誤／UX Playwright</td><td>設定頁 suite 有；<strong>已納入 CI</strong></td></tr><tr><td>9 華南 H1/H2</td><td><strong>PARTIAL：post-login 仍 heuristic</strong></td></tr><tr><td>10 刪 dual-write alias</td><td>PARTIAL</td></tr></tbody></table><p>合約：watermark = <code>coveredThrough</code>（不是 finish wall-clock）；<code>providerTransactionId</code> 方案版本化；dual-key 優先 <code>lastSyncAt</code> &gt; <code>last_sync_at</code>。</p><h2 id="真機閘-不得用-jvm-代替" tabindex="-1">真機閘（不得用 JVM 代替） <a class="header-anchor" href="#真機閘-不得用-jvm-代替" aria-label="Permalink to &quot;真機閘（不得用 JVM 代替）&quot;">​</a></h2><h3 id="第一銀行-0c" tabindex="-1">第一銀行 0C <a class="header-anchor" href="#第一銀行-0c" aria-label="Permalink to &quot;第一銀行 0C&quot;">​</a></h3><p>見 <a href="/operations/android-native-bank-apk.html">Android-Native-Bank-APK</a>。證據：第二次同步 query 窗、versionName、裝置。</p><h3 id="華南-h1-h2" tabindex="-1">華南 H1/H2 <a class="header-anchor" href="#華南-h1-h2" aria-label="Permalink to &quot;華南 H1/H2&quot;">​</a></h3><p>H0 只凍登入頁。H1＝帳戶列表結構、H2＝至少一筆交易 DOM／JSON。沒有真實登入證據前，禁止把 heuristic 寫成已凍合約。失敗碼 <code>hua_nan_account_list_not_found</code> 代表尚未通過 H1。</p><h2 id="android-only" tabindex="-1">Android-only <a class="header-anchor" href="#android-only" aria-label="Permalink to &quot;Android-only&quot;">​</a></h2><p>非 Android：支援矩陣 + recovery CTA，不要靜默 redirect。除錯 web 路徑不是生產同步。</p><h2 id="引用" tabindex="-1">引用 <a class="header-anchor" href="#引用" aria-label="Permalink to &quot;引用&quot;">​</a></h2><ul><li><a href="/operations/sync-operations-runbooks.html">Sync-Operations-Runbooks</a></li><li><a href="/operations/android-native-bank-apk.html">Android-Native-Bank-APK</a></li><li><a href="https://github.com/StrawCoding/StrawMoneyBook/blob/main/frontend/test/bank-sync-android-source.test.js" target="_blank" rel="noreferrer"><code>frontend/test/bank-sync-android-source.test.js</code></a></li></ul>',14)])])}const p=a(d,[["render",n]]);export{b as __pageData,p as default};
